 function positioningCard(a:any){const p=a.positioning;const wallLine=(w:any,label:string,persist:any)=>'<h4>'+label+'</h4><div class="mb-value">'+fmt(w.from,0)+' → '+fmt(w.strike,0)+' · OI '+fmt(w.oi,0)+'</div>'+note('Spot distance '+sign(p.spot===null||w.strike===null?null:w.strike-p.spot)+' points · same-strike OI Δ '+sign(w.oiDelta,0)+' · '+w.reason)+note('Continuous recorded run: '+persist.samples+' samples since '+when(persist.since));return '<section class="mb-box '+biasClass(a)+'"><h3>'+a.symbol+(a.symbol==='BANKNIFTY'?' · monthly observation':'')+'</h3>'+note('Expiry '+a.expiry+' · positioning '+when(p.at))+metric(p.spotMetric,'Spot at positioning timestamp')+note('Full PCR '+fmt(a.pcr.value,4)+' · '+fmt(a.pcr.from,4)+' → '+fmt(a.pcr.value,4)+' · Δ '+sign(a.pcr.delta,4)+' · '+when(a.pcr.fromAt)+' → '+when(a.pcr.at))+wallLine(a.callWall,'Call wall',p.callPersistence)+wallLine(a.putWall,'Put wall',p.putPersistence)+note('Selected '+win+' baseline '+(p.baselineAvailable?'available':'unavailable')+' · '+p.samples+' returned chain samples · '+p.gaps.length+' observed gaps >3m')+context(a)+'</section>';}
