  const scale=Math.max(...valid.map((r:any)=>Math.abs(r.value)),0),responseDate=snapshot?.timestamp&&Number.isFinite(Date.parse(snapshot.timestamp))?new Date(snapshot.timestamp).toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'}):null;
